import{_ as s,r as t,o as a,c as r,e as i,a as l,s as g}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"Managing Administrators - October CMS User Guide","titleTemplate":false,"description":"Create an administrator, assign a role, and check the event log","frontmatter":{"subtitle":"Create an administrator, assign a role, and check the event log"},"headers":[{"level":2,"title":"Create a New Administrator","slug":"create-a-new-administrator","link":"#create-a-new-administrator","children":[]},{"level":2,"title":"Assign a Role","slug":"assign-a-role","link":"#assign-a-role","children":[]},{"level":2,"title":"Check the Event Log","slug":"check-the-event-log","link":"#check-the-event-log","children":[]},{"level":2,"title":"View the Mail Configuration","slug":"view-the-mail-configuration","link":"#view-the-mail-configuration","children":[]},{"level":2,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}],"relativePath":"user-guide/quickstart/backend/managing-admins.md","filePath":"user-guide/quickstart/backend/managing-admins.md"}'),h={name:"user-guide/quickstart/backend/managing-admins.md"};function d(c,e,m,u,p,f){const n=t("pre-heading"),o=t("post-heading");return a(),r("div",null,[i(n),e[0]||(e[0]=l("h1",null,"Managing Administrators",-1)),i(o),e[1]||(e[1]=g('<p>Every person who logs in to the backend is an administrator. Right now you are the only one. Let&#39;s create a second account, assign it a role, and verify that the system sent an invitation email.</p><h2 id="create-a-new-administrator"><a href="#create-a-new-administrator" class="header-anchor">#</a> Create a New Administrator</h2><ol><li>Open the <strong>Settings</strong> area from the main menu.</li><li>Click <strong>Administrators</strong> in the left-hand sidebar.</li><li>Click the <strong>New Administrator</strong> button.</li><li>Fill in the details, using any name and email you like. For example: <ul><li><strong>First Name</strong>: <code>Test</code></li><li><strong>Last Name</strong>: <code>Editor</code></li><li><strong>Email</strong>: <code>editor@example.com</code></li><li><strong>Username</strong>: <code>editor</code></li><li><strong>Password</strong>: pick something simple for now (this is just a local test).</li></ul></li><li>Leave the <strong>Send invitation by email</strong> checkbox ticked so the new administrator receives their login details.</li><li>Click <strong>Create</strong>.</li></ol><p>Your new administrator now appears in the list.</p><h2 id="assign-a-role"><a href="#assign-a-role" class="header-anchor">#</a> Assign a Role</h2><p>By default the new account has no restrictions. Let&#39;s give it a specific role so it only has access to certain areas.</p><ol><li>Click on <strong>Test Editor</strong> in the administrator list to open their profile.</li><li>Find the <strong>Role</strong> options and select <strong>Publisher</strong> (or whichever role fits; you can browse the available roles to see what permissions each one includes).</li><li>Click <strong>Save</strong>.</li></ol><p>That administrator is now limited to the permissions defined by their role. They won&#39;t see settings or areas they don&#39;t have access to.</p><div class="custom-block tip"><p>You can manage roles under <strong>Settings → Role Permissions</strong>. Roles are just named groups of permissions, so create as many as your team needs.</p></div><h2 id="check-the-event-log"><a href="#check-the-event-log" class="header-anchor">#</a> Check the Event Log</h2><p>When you created that administrator, the system sent the invitation email. Since your site is probably using the <strong>Log</strong> mail driver (the default for local development), the email was written to the log file instead of actually being sent. Let&#39;s check.</p><ol><li>Go to <strong>Settings → Logs → Event Log</strong>.</li><li>Look for a recent entry related to the invitation email. Click it to see the full details.</li></ol><p>This is where you will check for errors, debug issues, and verify that things like email delivery are working. Get in the habit of checking the event log when something doesn&#39;t seem right.</p><h2 id="view-the-mail-configuration"><a href="#view-the-mail-configuration" class="header-anchor">#</a> View the Mail Configuration</h2><p>Now let&#39;s see where you would configure a real mail provider for production.</p><ol><li>Navigate to <strong>Settings → Mail → Mail Configuration</strong>.</li><li>You will see the current <strong>Send Method</strong>. It is most likely set to <strong>Log</strong>, which writes emails to the log file instead of sending them.</li><li>In production, you would change this to <strong>SMTP</strong>, <strong>Mailgun</strong>, <strong>Postmark</strong>, or another provider and fill in your credentials.</li><li>The <strong>Send Test Message</strong> button lets you verify your settings before going live.</li></ol><p>You don&#39;t need to change anything right now. Just know where this setting lives for when you are ready to deploy.</p><h2 id="next-steps"><a href="#next-steps" class="header-anchor">#</a> Next Steps</h2><p>You have created an administrator, assigned a role, and found the event log and mail settings. Continue to <a href="./system-updates.html">System Updates</a> to learn how to manage plugins and keep your site up to date.</p>',19))])}const k=s(h,[["render",d]]);export{w as __pageData,k as default};
